// The layout engine's Unicode property tables (Typesetting/UnicodeData.cs, generated by
// build/generate-unicode-tables.ps1): values of known characters, defaults for unassigned code points, and agreement
// with the Unicode version .NET uses.

using System.Globalization;
using Filee.Engines.Typesetting;

namespace Filee.Engines.Tests;

public class UnicodeDataTests
{
    [Theory]
    [InlineData(' ', nameof(LineBreakClass.SP))]
    [InlineData('a', nameof(LineBreakClass.AL))]
    [InlineData('0', nameof(LineBreakClass.NU))]
    [InlineData('(', nameof(LineBreakClass.OP))]
    [InlineData('\n', nameof(LineBreakClass.LF))]
    [InlineData(0x00A0, nameof(LineBreakClass.GL))] // no-break space
    [InlineData(0x200B, nameof(LineBreakClass.ZW))]
    [InlineData(0x200D, nameof(LineBreakClass.ZWJ))]
    [InlineData('가', nameof(LineBreakClass.H2))] // LV syllable
    [InlineData('각', nameof(LineBreakClass.H3))] // LVT syllable
    [InlineData(0x1100, nameof(LineBreakClass.JL))]
    [InlineData(0x1161, nameof(LineBreakClass.JV))]
    [InlineData(0x11A8, nameof(LineBreakClass.JT))]
    [InlineData('一', nameof(LineBreakClass.ID))]
    [InlineData('。', nameof(LineBreakClass.CL))]
    [InlineData('ぁ', nameof(LineBreakClass.CJ))]
    [InlineData('ก', nameof(LineBreakClass.SA))] // Thai: dictionary breaking
    [InlineData('א', nameof(LineBreakClass.HL))]
    [InlineData(0x1B13, nameof(LineBreakClass.AK))] // Balinese ka (Aksara, Unicode 15.1)
    [InlineData(0x0915, nameof(LineBreakClass.AL))] // Devanagari ka
    [InlineData(0x094D, nameof(LineBreakClass.CM))] // Devanagari virama
    [InlineData(0x1F600, nameof(LineBreakClass.ID))] // emoji
    [InlineData(0x3FFFD, nameof(LineBreakClass.ID))] // unassigned, CJK default
    [InlineData(0xE0080, nameof(LineBreakClass.XX))] // unassigned
    public void Line_break_classes(int codePoint, string expected)
    {
        Assert.Equal(Enum.Parse<LineBreakClass>(expected), UnicodeData.GetLineBreak(codePoint));
    }

    [Theory]
    [InlineData('a', nameof(BidiClass.L))]
    [InlineData('א', nameof(BidiClass.R))]
    [InlineData('ب', nameof(BidiClass.AL))]
    [InlineData('1', nameof(BidiClass.EN))]
    [InlineData(0x0663, nameof(BidiClass.AN))] // Arabic-Indic three
    [InlineData(0x0301, nameof(BidiClass.NSM))]
    [InlineData(' ', nameof(BidiClass.WS))]
    [InlineData(0x2067, nameof(BidiClass.RLI))]
    [InlineData(0x2069, nameof(BidiClass.PDI))]
    [InlineData(0x05FF, nameof(BidiClass.R))] // unassigned in the Hebrew block: right-to-left by default
    [InlineData(0x07B2, nameof(BidiClass.AL))] // unassigned in an Arabic range
    [InlineData(0x20BF, nameof(BidiClass.ET))] // bitcoin sign
    [InlineData(0xE0080, nameof(BidiClass.BN))] // unassigned default ignorable
    public void Bidi_classes(int codePoint, string expected)
    {
        Assert.Equal(Enum.Parse<BidiClass>(expected), UnicodeData.GetBidiClass(codePoint));
    }

    [Theory]
    [InlineData('A', nameof(EastAsianWidth.Narrow))]
    [InlineData('가', nameof(EastAsianWidth.Wide))]
    [InlineData('“', nameof(EastAsianWidth.Ambiguous))]
    [InlineData('…', nameof(EastAsianWidth.Ambiguous))]
    [InlineData('é', nameof(EastAsianWidth.Ambiguous))]
    [InlineData('Ａ', nameof(EastAsianWidth.Fullwidth))]
    [InlineData('ｱ', nameof(EastAsianWidth.Halfwidth))]
    [InlineData('ب', nameof(EastAsianWidth.Neutral))]
    [InlineData(0x2A6DF, nameof(EastAsianWidth.Wide))]
    [InlineData(0x3FFFD, nameof(EastAsianWidth.Wide))] // unassigned, CJK default
    public void East_asian_widths(int codePoint, string expected)
    {
        Assert.Equal(Enum.Parse<EastAsianWidth>(expected), UnicodeData.GetEastAsianWidth(codePoint));
    }

    [Theory]
    [InlineData('a', nameof(UnicodeScript.Latin), "Latn")]
    [InlineData('가', nameof(UnicodeScript.Hangul), "Hang")]
    [InlineData(0x1100, nameof(UnicodeScript.Hangul), "Hang")]
    [InlineData('一', nameof(UnicodeScript.Han), "Hani")]
    [InlineData('あ', nameof(UnicodeScript.Hiragana), "Hira")]
    [InlineData('ア', nameof(UnicodeScript.Katakana), "Kana")]
    [InlineData('ー', nameof(UnicodeScript.Common), "Zyyy")]
    [InlineData(0x0301, nameof(UnicodeScript.Inherited), "Zinh")]
    [InlineData('ب', nameof(UnicodeScript.Arabic), "Arab")]
    [InlineData(0x0915, nameof(UnicodeScript.Devanagari), "Deva")]
    [InlineData(0x0A95, nameof(UnicodeScript.Gujarati), "Gujr")]
    [InlineData('ก', nameof(UnicodeScript.Thai), "Thai")]
    [InlineData(0x1C89, nameof(UnicodeScript.Cyrillic), "Cyrl")] // new in Unicode 16.0
    [InlineData(0x10940, nameof(UnicodeScript.Unknown), "Zzzz")] // Sidetic, Unicode 17.0: not in the tables yet
    [InlineData(0xE000, nameof(UnicodeScript.Unknown), "Zzzz")] // private use
    public void Scripts_and_their_iso_codes(int codePoint, string expected, string code)
    {
        var script = Enum.Parse<UnicodeScript>(expected);
        Assert.Equal(script, UnicodeData.GetScript(codePoint));
        Assert.Equal(code, script.IsoCode());
    }

    [Fact]
    public void Code_points_outside_the_code_space_get_the_defaults()
    {
        Assert.Equal(LineBreakClass.XX, UnicodeData.GetLineBreak(0x110000));
        Assert.Equal(UnicodeScript.Unknown, UnicodeData.GetScript(-1));
        Assert.Equal(EastAsianWidth.Neutral, UnicodeData.GetEastAsianWidth(int.MaxValue));
    }

    [Fact]
    public void Tables_describe_the_characters_dotnet_knows()
    {
        // Same Unicode version as .NET: what .NET calls unassigned has no script, and every code point without a script
        // is unassigned, private use or a surrogate.
        Assert.Equal("16.0.0", UnicodeData.Version);
        for (var codePoint = 0; codePoint <= 0x10FFFF; codePoint++)
        {
            var category = CharUnicodeInfo.GetUnicodeCategory(codePoint);
            var unknown = UnicodeData.GetScript(codePoint) == UnicodeScript.Unknown;
            var expected = category is UnicodeCategory.OtherNotAssigned or UnicodeCategory.PrivateUse or UnicodeCategory.Surrogate;
            if (unknown != expected)
                Assert.Fail($"U+{codePoint:X4} is {category} in .NET but has the script {UnicodeData.GetScript(codePoint)}.");
        }
    }

    [Fact]
    public void Code_points_are_read_across_surrogate_pairs()
    {
        Assert.Equal(0x1F600, UnicodeData.CodePointAt("a\U0001F600", 1));
        Assert.Equal(0xD800, UnicodeData.CodePointAt("\uD800a", 0)); // a lone surrogate is itself
        Assert.Equal(LineBreakClass.SG, UnicodeData.GetLineBreak(0xD800));
    }
}
